import json, collections

workers = snapshot["workers"]
total = len(workers)
print(f"Total workers: {total}")

# Recompute engine concentration
engine_counts = collections.Counter(w["engine"] for w in workers)
print("\n=== ENGINE (recomputed) ===")
for ident, cnt in engine_counts.most_common():
    print(f"  {ident}: {cnt} ({cnt/total:.6f})")

# Recompute trigger concentration
trigger_counts = collections.Counter(w["trigger"] for w in workers)
print("\n=== TRIGGER (recomputed) ===")
for ident, cnt in trigger_counts.most_common():
    print(f"  {ident}: {cnt} ({cnt/total:.6f})")

# Recompute effect concentration
effect_counts = collections.Counter(w["effect"] for w in workers if w["effect"] is not None)
print("\n=== EFFECT (recomputed) ===")
for ident, cnt in effect_counts.most_common():
    print(f"  {ident}: {cnt} ({cnt/total:.6f})")

# Recompute digest concentration (current version digest from version_history)
digest_counts = collections.Counter()
for w in workers:
    vh = w.get("version_history", [])
    cv = w.get("current_version")
    for entry in vh:
        if entry.get("version") == cv:
            digest_counts[entry["digest"]] += 1
            break
print("\n=== DIGEST (recomputed) ===")
for ident, cnt in digest_counts.most_common():
    print(f"  {ident}: {cnt} ({cnt/total:.6f})")

# Now compare with established measurement
meas = snapshot["dependency_concentration"]["measurement"]
print("\n=== COMPARISON WITH ESTABLISHED MEASUREMENT ===")
print(f"Established worker_count: {meas['worker_count']}")

for dtype in ["engine", "trigger", "effect", "digest"]:
    est = {e["identity"]: (e["worker_count"], e["fleet_share"]) for e in meas["by_type"][dtype]}
    if dtype == "effect":
        recomputed = {k: (v, v/total) for k, v in effect_counts.items()}
    elif dtype == "engine":
        recomputed = {k: (v, v/total) for k, v in engine_counts.items()}
    elif dtype == "trigger":
        recomputed = {k: (v, v/total) for k, v in trigger_counts.items()}
    elif dtype == "digest":
        recomputed = {k: (v, v/total) for k, v in digest_counts.items()}

    match = True
    for ident in set(list(est.keys()) + list(recomputed.keys())):
        e = est.get(ident, (0, 0))
        r = recomputed.get(ident, (0, 0))
        if e[0] != r[0]:
            match = False
            print(f"  MISMATCH [{dtype}] {ident}: established={e[0]}, recomputed={r[0]}")
    if match:
        print(f"  {dtype}: ALL MATCH ✓")

# Let's also look at the current incident and worker health details
# Check for any workers with exceptions or non-ok status
for w in workers:
    s = w["summary"]
    if s["last_status"] != "ok" or s["exceptions"] > 0 or s["all_time_exceptions"] > 0:
        print(f"WORKER ISSUE: {w['name']} | last_status={s['last_status']} | exceptions={s['exceptions']} | all_time_exc={s['all_time_exceptions']} | investigation={s['investigation']}")

print("\n=== PENDING EXCEPTIONS ===")
for pe in snapshot.get("pending_exceptions", []):
    print(f"  {pe['worker']}: state={pe['state']}, failure={pe['failure']}")

# Check the reservation workers specifically
print("\n=== RESERVATION WORKERS DETAIL ===")
for w in workers:
    if w["task"] == "reservation":
        s = w["summary"]
        print(f"  {w['name']} | customer={w['customer']} | last_status={s['last_status']} | effects_failed={s['effects_failed']} | committing={w['committing']} | effect={w['effect']}")
        for run in w["recent_runs"][:2]:
            print(f"    run: ok={run['ok']} decision={run.get('decision')} reason={run.get('reason')} problems={run.get('problems')}")

# Check digest-to-engine mapping for cross-cutting analysis
print("\n=== DIGEST -> ENGINE MAPPING ===")
digest_engine = collections.defaultdict(lambda: collections.Counter())
for w in workers:
    vh = w.get("version_history", [])
    cv = w.get("current_version")
    for entry in vh:
        if entry.get("version") == cv:
            digest_engine[entry["digest"]][w["engine"]] += 1
            break
for digest, engines in digest_engine.items():
    parts = ", ".join(f"{e}:{c}" for e, c in engines.most_common())
    print(f"  {digest[:12]}... -> {parts}")

# Final check: the reservation workers all share the same digest - let's verify
# and check if the failing worker rese-a-inv shares the same engine/digest as the healthy ones
print("=== RESERVATION WORKERS - SHARED COMPONENTS ===")
for w in workers:
    if w["task"] == "reservation":
        digest = None
        for entry in w["version_history"]:
            if entry["version"] == w["current_version"]:
                digest = entry["digest"]
        print(f"  {w['name']}: engine={w['engine']}, digest={digest}, effect={w['effect']}, customer={w['customer']}, trigger={w['trigger']}")
        print(f"    last_status={w['summary']['last_status']}, effects_failed={w['summary']['effects_failed']}, investigation={w['summary']['investigation']}")

# Check if the PermissionError on rese-a-inv could affect the other reservation workers
# since they all share the same engine and effect
print("\n=== ALL WORKERS SHARING append_to_reservations EFFECT ===")
for w in workers:
    if w["effect"] == "append_to_reservations":
        print(f"  {w['name']}: last_status={w['summary']['last_status']}, effects_failed={w['summary']['effects_failed']}")

